bool consume_front(std::size_t count) noexcept {
        if (count > used_) return false;
        const std::size_t left = used_ - count;
        for (std::size_t index = 0; index < left; ++index) {
            bytes_[index] = bytes_[count + index];
        }
        used_ = left;
        return true;
    }

inline constexpr std::size_t kMaxPayloadBytes = 32;
inline constexpr std::size_t kHeaderBytes = 2;
inline constexpr std::size_t kMaxFrameBytes = 35;
inline constexpr std::size_t kReceiveCapacity = 64;
inline constexpr std::uint16_t kMaxLength = 33;

static_assert(kMaxFrameBytes == kHeaderBytes + 1 + kMaxPayloadBytes,
              "frame size must equal header + type + max payload");
static_assert(kReceiveCapacity > kMaxFrameBytes,
              "receive buffer must hold a whole maximum frame");

// One application frame. `size` is the payload length (0..kMaxPayloadBytes).
// A freshly decoded frame has a zeroed unused payload tail.
struct Frame {
  std::uint8_t type{};
  std::array<std::uint8_t, kMaxPayloadBytes> payload{};
  std::size_t size{};
};

// One encoded frame. `size` is the total encoded length (3 + payload length).
struct EncodedFrame {
  std::array<std::uint8_t, kMaxFrameBytes> bytes{};
  std::size_t size{};
};

inline bool encode_frame(const Frame& frame, EncodedFrame& out) noexcept {
  if (frame.size > kMaxPayloadBytes) {
    return false;
  }
  EncodedFrame candidate{};
  const std::uint16_t len =
      static_cast<std::uint16_t>(frame.size + std::size_t{1});
  candidate.bytes[0] = static_cast<std::uint8_t>(len & 0xFFu);
  candidate.bytes[1] = static_cast<std::uint8_t>((len >> 8) & 0xFFu);
  candidate.bytes[2] = frame.type;
  for (std::size_t i = 0; i < frame.size; ++i) {
    candidate.bytes[kHeaderBytes + 1 + i] = frame.payload[i];
  }
  candidate.size = kHeaderBytes + 1 + frame.size;
  out = candidate;
  return true;
}

ParseStatus next(Frame& out) noexcept {
    if (failed_) {
      return ParseStatus::error;
    }
    if (buffer_.size() < kHeaderBytes) {
      return ParseStatus::need_more;
    }
    const std::uint8_t* p = buffer_.data();
    const std::uint16_t len = static_cast<std::uint16_t>(
        static_cast<std::uint16_t>(p[0]) |
        (static_cast<std::uint16_t>(p[1]) << 8));
    if (len < 1u || len > kMaxLength) {
      failed_ = true;
      (void)buffer_.consume_front(buffer_.size());
      return ParseStatus::error;
    }
    const std::size_t total = kHeaderBytes + static_cast<std::size_t>(len);
    if (buffer_.size() < total) {
      return ParseStatus::need_more;
    }
    Frame candidate{};
    candidate.type = p[kHeaderBytes];
    for (std::size_t i = 1; i < len; ++i) {
      candidate.payload[i - 1] = p[kHeaderBytes + i];
    }
    candidate.size = static_cast<std::size_t>(len) - 1;
    (void)buffer_.consume_front(total);
    out = candidate;
    return ParseStatus::frame;
  }

bool append(const std::uint8_t* data, std::size_t count) noexcept {
    if (failed_) {
      return false;
    }
    if (!buffer_.append(data, count)) {
      failed_ = true;
      (void)buffer_.consume_front(buffer_.size());
      return false;
    }
    return true;
  }

int run_server(unsigned port_arg, std::size_t read_cap) {
  int error = 0;
  std::uint16_t actual_port = 0;
  study_net::Socket listener = study_net::listen_loopback(
      static_cast<std::uint16_t>(port_arg), actual_port, error);
  if (!listener.valid()) {
    return fail_error("listen", "listen_loopback", error);
  }
  std::printf("LISTEN %u\n", static_cast<unsigned>(actual_port));
  std::fflush(stdout);

  study_net::Socket connection = study_net::accept_one(listener, error);
  listener.reset();
  if (!connection.valid()) {
    return fail_error("accept", "accept_one", error);
  }

  study_net::FrameParser parser;
  std::uint8_t buffer[kReadWindow];
  std::size_t frames = 0;

  for (;;) {
    const study_net::StreamResult result =
        study_net::receive_some(connection, buffer, read_cap);
    if (result.status == study_net::StreamStatus::error) {
      return fail_error("receive", "receive_some", result.error);
    }
    if (result.status == study_net::StreamStatus::eof) {
      break;
    }
    if (result.count == 0) {
      return fail("receive", "no_progress");
    }
    if (!parser.append(buffer, result.count)) {
      return fail("append", "overflow");
    }
    for (;;) {
      study_net::Frame frame{};
      const study_net::ParseStatus status = parser.next(frame);
      if (status == study_net::ParseStatus::need_more) {
        break;
      }
      if (status == study_net::ParseStatus::error) {
        return fail("parse", "malformed_length");
      }
      if (frame.type != kRequestType) {
        return fail("parse", "unknown_type");
      }
      study_net::Frame reply{};
      reply.type = kReplyType;
      reply.size = frame.size;
      reply.payload = frame.payload;
      study_net::EncodedFrame encoded{};
      if (!study_net::encode_frame(reply, encoded)) {
        return fail("encode", "payload_too_large");
      }
      if (!send_all(connection, encoded.bytes.data(), encoded.size, encoded.size,
                    "send_reply")) {
        return 1;
      }
      print_frame_hex(frame);
      ++frames;
    }
  }

  if (parser.pending_bytes() != 0) {
    return fail("eof", "truncated_frame");
  }
  int shut_error = 0;
  if (!study_net::shutdown_send(connection, shut_error)) {
    return fail_error("shutdown", "shutdown_send", shut_error);
  }
  std::printf("FRAMES %zu\n", frames);
  std::fflush(stdout);
  return 0;
}
